      "check_id": "CKV_AWS_288",
      "title": "IAM policy has an 'Allow' statement with a wildcard resource",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "HIGH",
      "explanation": "The policy allows actions on all resources, potentially granting excessive permissions"
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies do not allow 'ssm:StartSession' permission on all resources",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "CRITICAL",
      "explanation": "Allowing 'ssm:StartSession' on all resources could enable unauthorized access to instances"
    }
  ],
  "patched_code": ```hcl
resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
          "ssm:DescribeSessions",
          "ssm:GetConnectionStatus",
          "ssm:DescribeInstanceProperties",
          "ssm:TerminateSession",
          "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Effect   = "Allow"
        Action = [
          "ssm:StartSession"
        ]
        Resource = "arn:aws:ssm:*:*:document/*"
      }
    ]
  })
}
```,
  "fix_summary": "Restricted 'Resource' to specific ARNs for 'ssm:StartSession' and other actions, reducing the scope of allowed actions"
}
